<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, nextTick, ref, watch } from 'vue'
import { session } from '../session'
import { analyzePlanMaterialClaims, commitPlanMaterialImport, clearPlanMaterialLibrary, deletePlanMaterialClaim, getLiveAgentPlanProductLinks, getPlanMaterialClaims, getPlanMaterialObjects, savePlanMaterialObjects, resolvePlanMaterialDuplicates, reviewPlanMaterialClaims, splitPlanMaterialClaim, updatePlanMaterialClaim, updatePlanMaterialLinkDisplayName, setPlanMaterialClaimBenefit, type MaterialCondition, type MaterialLinkObject, type MaterialStoreObject, type MaterialObjectTarget } from '../api'
import { canConfirm, compareLibrary, conditionLabel, hasCondition, isRisk, isTodo, objectKeys, objectLabel, row, toInput, resolveRowObjects, assignedTargets, targetsFor, matchesObject, genericStore, duplicateGroups, importReviewGroups, resolvedDuplicate, duplicateRemainder, type DuplicateGroup, type ImportRow } from '../materialImport'
const props=defineProps<{planId:number;links?:{id?:number;link_key:string;product_name?:string;display_name?:string}[]}>()
const text=ref(''),draft=ref<ImportRow[]>([]),library=ref<ImportRow[]>([]),selected=ref(new Set<string>())
const source=ref<'draft'|'library'|'all'>('draft'),view=ref<'object'|'todo'|'duplicates'>('object'),filter=ref('all'),object=ref('all'),search=ref(''),topic=ref('all')
const expandedObjects=ref(new Set<string>()),objectAttribute=ref('all')
const benefitGroup='__benefit__'
const pendingClaimRemoval=ref<string|null>(null)
const busy=ref(false),questionsLoading=ref(false),loaded=ref(false),error=ref(''),notice=ref(''),warnings=ref<string[]>([])
const renamingLinkId=ref<number|null>(null),renamingName=ref(''),renameInput=ref<HTMLInputElement|HTMLInputElement[]|null>(null)
const catalogLinks=ref<MaterialLinkObject[]>([]),catalogStores=ref<MaterialStoreObject[]>([]),catalogRevision=ref(0)
const bindingsOpen=ref(false),bindingsDraft=ref<MaterialStoreObject[]>([]),newStoreName=ref('')
const questions=ref<{q:string;claim_ids:string[]}[]>([]),question=ref('')
const libraryRevision=ref(''),importRevision=ref(''),importObjectRevision=ref(0),importRows=ref<ImportRow[]>([]),importLibrary=ref<ImportRow[]>([]),importChoices=ref<Record<string,'replace'|'keep'>>({})
const importGroups=computed(()=>importReviewGroups(importRows.value,importLibrary.value,storeObjects.value))
const importAppendCount=computed(()=>importRows.value.filter(it=>!importGroups.value.some(g=>g.draft.some(x=>x.uid===it.uid))).length)
const importReady=computed(()=>importRows.value.length>0&&importGroups.value.every(g=>!!importChoices.value[g.key]))
const conflicts=ref<{topic?:string;statements?:string[];issue?:string}[]>([])
const confirmOpen=ref(false),scopeItem=ref<ImportRow|null>(null),scopeChoices=ref<string[]>([]),scopeSearch=ref('')
const editItem=ref<ImportRow|null>(null),edit=ref<ImportRow|null>(null),splitItem=ref<ImportRow|null>(null),splitText=ref(''),splitRows=ref<ImportRow[]>([])
type PredicateEditor={field:string;op:string;values:string;raw:string;universe:string;original?:MaterialCondition;opaque?:boolean}
const predicates=ref<PredicateEditor[]>([]),exceptions=ref<PredicateEditor[]>([])
const editorContent=ref<HTMLTextAreaElement|null>(null)
const editCanSave=computed(()=>!!edit.value&&(edit.value.destination==='qa'?!!edit.value.question?.trim()&&!!edit.value.answer?.trim():!!edit.value.content.trim()))
const predicateFields=[{value:'region',label:'地区'},{value:'channel',label:'购买渠道'},{value:'time',label:'时间'},{value:'amount',label:'订单金额'},{value:'quantity',label:'数量'},{value:'other',label:'其它'}]
const predicateOps=[{value:'eq',label:'等于'},{value:'neq',label:'不等于'},{value:'in',label:'属于其中'},{value:'not_in',label:'不属于其中'},{value:'gt',label:'大于'},{value:'gte',label:'大于或等于'},{value:'lt',label:'小于'},{value:'lte',label:'小于或等于'},{value:'between',label:'在区间内'},{value:'and',label:'同时满足'},{value:'or',label:'任意满足'},{value:'raw',label:'原文条件'}]
let epoch=0,questionRevision=0
const actorKey=computed(()=>session.bootstrap?.actor ? `${session.bootstrap.actor.tenant_id}:${session.bootstrap.actor.user_id}`:'')
const storageKey=computed(()=>actorKey.value?`material-import:v2:${actorKey.value}:${props.planId}`:'')
const all=computed(()=>[...draft.value,...library.value])
const currentRows=computed(()=>all.value.filter(it=>source.value==='all'||(source.value==='library'?!!it.id:!it.id)))
const scoped=computed(()=>currentRows.value.filter(it=>matchesObject(it,object.value,storeObjects.value,false)))
const visible=computed(()=>scoped.value.filter(it=>{
 if(objectAttribute.value===benefitGroup&&!it.is_benefit)return false
 if(objectAttribute.value!=='all'&&objectAttribute.value!==benefitGroup&&attributeKey(it)!==objectAttribute.value)return false
 if(topic.value!=='all'&&(it.topic||it.attribute)!==topic.value)return false
 if(search.value.trim()&&!`${scopeLabel(it)} ${it.content} ${it.topic} ${it.claim_key} ${it.source_quote} ${it.question||''} ${it.answer||''}`.toLowerCase().includes(search.value.trim().toLowerCase()))return false
 if(view.value==='todo'&&!isTodo(it))return false
 if(view.value==='duplicates'&&!duplicateUIDs.value.has(it.uid))return false
 return filter.value==='todo'?isTodo(it):filter.value==='risk'?isRisk(it):filter.value==='split'?!!it.needs_split:filter.value==='conflict'?it.rowState==='conflict'||it.rowState==='lib_conflict':true
}))
const linkObjects=computed<MaterialLinkObject[]>(()=>catalogLinks.value.length?catalogLinks.value:(props.links||[]).filter(l=>l.id).map(l=>({id:l.id!,link_key:l.link_key,product_name:l.product_name,display_name:l.display_name})))
const storeObjects=computed<MaterialStoreObject[]>(()=>{
 const names=new Set(catalogStores.value.map(s=>s.name));for(const it of all.value)for(const t of targetsFor(it))if(t.kind==='store'&&t.store_name&&!genericStore(t.store_name))names.add(t.store_name)
 return [...names].sort((a,b)=>a.localeCompare(b,'zh')).map(name=>({name,link_ids:catalogStores.value.find(s=>s.name===name)?.link_ids||[]}))
})
const objectGroups=computed(()=>[{label:'商品 / 卡券链接',keys:linkObjects.value.map(l=>`link:${l.id}`)},{label:'门店 / 商家',keys:storeObjects.value.map(s=>`store:${s.name}`)}].filter(g=>g.keys.length))
const treeSections=computed(()=>[{label:'',keys:['all','plan']},...objectGroups.value,{label:'',keys:['unresolved']}])
const topics=computed(()=>[...new Set(all.value.map(it=>it.topic||it.attribute).filter(Boolean))])
const duplicates=computed(()=>duplicateGroups(all.value,storeObjects.value))
const duplicateUIDs=computed(()=>new Set(duplicates.value.flatMap(g=>g.rows.map(it=>it.uid))))
const visibleDuplicates=computed(()=>duplicates.value.filter(g=>(object.value==='all'||g.objectKey===object.value)&&g.rows.some(it=>visible.value.some(x=>x.uid===it.uid))))
const duplicateChoices=ref<Record<string,string>>({}),duplicateActionKey=ref('')
const draftDuplicateUIDs=computed(()=>new Set(duplicateGroups(draft.value,storeObjects.value).flatMap(g=>g.rows.map(it=>it.uid))))
function eligible(it:ImportRow){return canConfirm({...it,rowState:'new'})&&!draftDuplicateUIDs.value.has(it.uid)}
const chosen=computed(()=>draft.value.filter(it=>selected.value.has(it.uid)&&eligible(it)))
const selectedLibrary=computed(()=>library.value.filter(it=>selected.value.has(it.uid)))
const unresolvedConflicts=computed(()=>draft.value.filter(it=>draftDuplicateUIDs.value.has(it.uid)).length)
const counts=computed(()=>({all:all.value.length,todo:all.value.filter(isTodo).length,risk:all.value.filter(isRisk).length,split:all.value.filter(it=>it.needs_split).length,conflict:all.value.filter(it=>['conflict','lib_conflict'].includes(it.rowState||'')).length}))
const scopeOptions=computed(()=>['plan',...linkObjects.value.map(l=>`link:${l.id}`),...storeObjects.value.map(s=>`store:${s.name}`)].filter(key=>!scopeSearch.value.trim()||`${labelFor(key)} ${subtitleFor(key)}`.includes(scopeSearch.value.trim())))
function labelFor(key:string){return objectLabel(key,linkObjects.value)}
function startRenameLink(key:string){const link=linkObjects.value.find(l=>l.id===Number(key.slice(5)));if(!link||busy.value)return;renamingLinkId.value=link.id;renamingName.value=link.display_name?.trim()||'';nextTick(()=>{const input=renameInput.value;if(Array.isArray(input))input[0]?.focus();else input?.focus()})}
function cancelRenameLink(){if(busy.value)return;renamingLinkId.value=null;renamingName.value=''}
async function saveRenameLink(){const id=renamingLinkId.value;if(id===null)return;const next=renamingName.value.trim();if([...next].length>50){error.value='显示名称最多50个字';return}const current=linkObjects.value.find(l=>l.id===id);if(!current)return;if(next===(current.display_name?.trim()||'')){cancelRenameLink();return}await run(async()=>{await updatePlanMaterialLinkDisplayName(props.planId,id,next);catalogLinks.value=catalogLinks.value.map(link=>link.id===id?{...link,display_name:next}:link);renamingLinkId.value=null;renamingName.value='';notice.value='对象显示名称已更新。';await load()})}
function subtitleFor(key:string){if(key.startsWith('link:'))return linkObjects.value.find(l=>l.id===Number(key.slice(5)))?.product_name||'';if(key==='plan')return '本方案全部链接共同适用';if(key.startsWith('store:')){const store=storeObjects.value.find(s=>s.name===key.slice(6));return store?.link_ids.length?'关联 '+store.link_ids.map(id=>labelFor(`link:${id}`)).join('、'):'尚未关联链接'};return ''}
function scopeLabel(it:ImportRow){return objectKeys(it).map(labelFor).join('、')}
function clone<T>(v:T):T{return JSON.parse(JSON.stringify(v))}
function persist(){if(!storageKey.value)return;try{localStorage.setItem(storageKey.value,JSON.stringify({text:text.value,draft:draft.value,questions:questions.value,warnings:warnings.value}))}catch{notice.value='浏览器草稿保存失败，请保留原文后重试。'}}
function restore(){text.value='';draft.value=[];questions.value=[];warnings.value=[];if(!storageKey.value)return;try{const raw=JSON.parse(localStorage.getItem(storageKey.value)||'null');if(raw){text.value=String(raw.text||'');draft.value=Array.isArray(raw.draft)?raw.draft:[];questions.value=raw.questions||[];warnings.value=raw.warnings||[]}}catch{notice.value='原草稿无法读取，请重新粘贴。'}}
function toggle(uid:string){const next=new Set(selected.value);next.has(uid)?next.delete(uid):next.add(uid);selected.value=next}
async function toggleBenefit(it:ImportRow){await run(async()=>{
 const token=epoch,next=!it.is_benefit
 if(it.id){
  if(!it.revision)throw Error('请刷新库中资料后再标记福利')
  await setPlanMaterialClaimBenefit(props.planId,it.id,it.revision,next)
  if(token!==epoch)return
  await load()
 }else{
  draft.value=compareLibrary(draft.value.map(item=>item.uid===it.uid?{...item,is_benefit:next}:item),library.value)
  persist()
 }
 if(token===epoch)notice.value=next?'已标记为福利。':'已取消福利标记。'
})}
function selectGroup(key:string){const list=all.value.filter(it=>(key==='all'||matchesObject(it,key,storeObjects.value,false))&&(!!it.id||eligible(it)));selectRows(list)}
function selectRows(list:ImportRow[]){const next=new Set(selected.value),remove=list.length>0&&list.every(it=>next.has(it.uid));for(const it of list)remove?next.delete(it.uid):next.add(it.uid);selected.value=next}
function groupChecked(key:string){const list=all.value.filter(it=>(key==='all'||matchesObject(it,key,storeObjects.value,false))&&(!!it.id||eligible(it)));return list.length>0&&list.every(it=>selected.value.has(it.uid))}
function setSelected(){selected.value=new Set(draft.value.filter(eligible).map(it=>it.uid))}
function countFor(key:string){return currentRows.value.filter(it=>matchesObject(it,key,storeObjects.value,false)).length}
function attributeName(it:ImportRow,key:string){
 let name=(it.attribute||it.topic||it.claim_key||'其它').normalize('NFKC').trim(),owner=labelFor(key).normalize('NFKC')
 if(name.startsWith(owner)&&name.length>owner.length)name=name.slice(owner.length).replace(/^[\s·:：/\-]+/,'')
 return name.replace(/\s+/g,' ').trim()||'其它'
}
function attributeKey(it:ImportRow,key=object.value){return attributeName(it,key)}
function attributesFor(key:string){
 const groups=new Map<string,{key:string;label:string;count:number}>()
 const rows=currentRows.value.filter(it=>matchesObject(it,key,storeObjects.value,false))
 for(const it of rows){
  const attr=attributeKey(it,key),previous=groups.get(attr)
  if(previous){previous.count++;continue}
  groups.set(attr,{key:attr,label:attributeName(it,key),count:1})
 }
 const attributes=[...groups.values()].sort((a,b)=>a.label.localeCompare(b.label,'zh'))
 const benefits=rows.filter(it=>it.is_benefit).length
 return benefits?[{key:benefitGroup,label:'福利',count:benefits},...attributes]:attributes
}
function selectObject(key:string){
 object.value=key;objectAttribute.value='all';topic.value='all'
 if(key==='all')return
 const next=new Set(expandedObjects.value);next.has(key)?next.delete(key):next.add(key);expandedObjects.value=next
}
function selectAttribute(key:string,attribute:string){object.value=key;topic.value='all';objectAttribute.value=attribute}
async function load(){const token=epoch,plan=props.planId;try{const [out,catalog,products]=await Promise.all([getPlanMaterialClaims(plan),getPlanMaterialObjects(plan),getLiveAgentPlanProductLinks(plan)]);if(token!==epoch)return;const productById=new Map((products.items||[]).map(it=>[it.id,it]));catalogLinks.value=(catalog.links||[]).map(link=>{const product=productById.get(link.id);const labels=product?.field_labels as Record<string,string>|undefined;return {...link,display_name:labels?.display_name?.trim()||''}});catalogStores.value=catalog.stores||[];catalogRevision.value=catalog.revision||0;libraryRevision.value=out.library_revision||'';library.value=(out.items||[]).map(it=>resolveRowObjects(row(it),linkObjects.value));draft.value=compareLibrary(draft.value.map(it=>resolveRowObjects(it,linkObjects.value)),library.value);loaded.value=true;return true}catch(e){if(token===epoch)error.value=e instanceof Error?e.message:'读取资料失败';return false}}
async function run(work:()=>Promise<void>){if(busy.value)return;const token=epoch;busy.value=true;error.value='';try{await work()}catch(e){if(token===epoch)error.value=e instanceof Error?e.message:'操作失败，原数据已保留'}finally{if(token===epoch)busy.value=false}}
async function analyze(){await run(async()=>{const value=text.value.trim();if(!value)throw Error('请先粘贴资料');if([...value].length>20000)throw Error('一次最多20000字，请分批分析');const token=epoch;const out=await analyzePlanMaterialClaims(props.planId,value);if(token!==epoch)return;const incoming=(out.items||[]).map(it=>resolveRowObjects(row(it),linkObjects.value));if(!incoming.length)throw Error('没有可用草稿，原草稿已保留');warnings.value=out.parse_warnings||[];conflicts.value=out.conflicts||[];draft.value=compareLibrary(incoming,library.value);source.value='draft';view.value='object';resetFilters();duplicateActionKey.value='';edit.value=null;editItem.value=null;splitItem.value=null;scopeItem.value=null;confirmOpen.value=false;setSelected();persist();notice.value=`分析完成：${incoming.length}条；已替换原草稿，尚未入库。`})}
function clearDraft(){if(busy.value)return;error.value='';draft.value=[];selected.value=new Set();questions.value=[];warnings.value=[];conflicts.value=[];duplicateActionKey.value='';scopeItem.value=null;edit.value=null;editItem.value=null;splitItem.value=null;confirmOpen.value=false;importRows.value=[];resetFilters();source.value='draft';view.value='object';persist();notice.value='草稿已清除，粘贴原文保留。'}
async function clearLibrary(){await run(async()=>{const token=epoch,plan=props.planId;if(!await load()||token!==epoch)return;if(!library.value.length){notice.value='库中没有可清除的资料。';return};if(!window.confirm(`清除当前方案库中的 ${library.value.length} 条资料及其向量？草稿、商品卡和门店关联保留。`))return;const out=await clearPlanMaterialLibrary(plan,libraryRevision.value);if(token!==epoch)return;selected.value=new Set();duplicateActionKey.value='';await load();if(token!==epoch)return;draft.value=compareLibrary(draft.value,library.value);persist();notice.value=`已清除库中 ${out.removed} 条资料。`;})}
async function prepareConfirm(){await run(async()=>{const token=epoch;if(!await load()||token!==epoch)return;if(!chosen.value.length)throw Error('没有可入库的条目');if(!libraryRevision.value)throw Error('请刷新页面后重试');importRows.value=clone(chosen.value);importLibrary.value=clone(library.value);importRevision.value=libraryRevision.value;importObjectRevision.value=catalogRevision.value;importChoices.value={};confirmOpen.value=true})}
async function confirm(){await run(async()=>{if(!importReady.value)throw Error('请为库中已有的每组属性选择替换或保留');const list=importRows.value.map(it=>{const group=importGroups.value.find(g=>g.draft.some(x=>x.uid===it.uid));const item=toInput(it);delete item.replaces_id;return {item,action:group?importChoices.value[group.key]!:('append' as const)}});const token=epoch;const out=await commitPlanMaterialImport(props.planId,importRevision.value,importObjectRevision.value,list);if(token!==epoch)return;const ids=new Set(out.accepted_client_ids);draft.value=draft.value.filter(it=>!ids.has(it.uid));selected.value=new Set();persist();confirmOpen.value=false;source.value='library';notice.value=`已入库 ${out.added} 条，保留库中 ${out.kept} 项。未选择的草稿保留。`;await load()})}
function setView(next:'object'|'todo'|'duplicates'){view.value=next;filter.value='all';object.value=next==='todo'?'unresolved':'all';objectAttribute.value='all';topic.value='all';duplicateActionKey.value='';if(next==='duplicates')source.value='all'}
function chosenDuplicate(group:DuplicateGroup){return group.rows.find(it=>it.uid===duplicateChoices.value[group.key])}
async function resolveDuplicate(group:DuplicateGroup){duplicateActionKey.value=group.key;await run(async()=>{
 const keep=chosenDuplicate(group);if(!keep)throw Error('请选择需要保留的条目')
 const token=epoch,plan=props.planId,next=resolvedDuplicate(group,keep)
 const latest=duplicates.value.find(g=>g.key===group.key);if(!latest)throw Error('资料已变化，请重新比较')
 const stored=group.rows.filter(it=>it.id),removed=new Set(group.rows.map(it=>it.uid))
 if(stored.length){
  if(stored.some(it=>!it.revision))throw Error('请刷新资料后再处理库中重复属性')
  const keepId=keep.id||stored[0]!.id!
  await resolvePlanMaterialDuplicates(plan,keepId,stored.map(it=>({id:it.id!,revision:it.revision!})),toInput(next),group.objectKey)
  if(token!==epoch)return
  draft.value=draft.value.flatMap(it=>{if(!removed.has(it.uid))return [it];const remaining=duplicateRemainder(it,group.objectKey);return remaining?[remaining]:[]});persist();await load();if(token!==epoch)return
 }else{draft.value=draft.value.flatMap(it=>{if(!removed.has(it.uid))return [it];const remaining=duplicateRemainder(it,group.objectKey);return remaining?[remaining]:[]});if(draft.value.some(it=>it.uid===next.uid))next.uid=crypto.randomUUID();draft.value.push(next);draft.value=compareLibrary(draft.value,library.value);persist()}
 selected.value=new Set([...selected.value].filter(uid=>!removed.has(uid)));duplicateActionKey.value=''
 notice.value=`已处理${labelFor(group.objectKey)}下的重复属性，其它对象的内容和归属保留。`
})}
async function remove(it:ImportRow){
 if(busy.value)return
 if(pendingClaimRemoval.value!==it.uid){pendingClaimRemoval.value=it.uid;return}
 pendingClaimRemoval.value=null
 await run(async()=>{
  const token=epoch,plan=props.planId
  if(it.id){
   await deletePlanMaterialClaim(plan,it.id)
   if(token!==epoch)return
   await load()
  }else{
   draft.value=draft.value.filter(x=>x.uid!==it.uid)
   selected.value.delete(it.uid)
   persist()
  }
 })
}
async function removeSelected(){if(!selectedLibrary.value.length||!window.confirm(`移除选中的${selectedLibrary.value.length}条库中资料？`))return;await run(async()=>{const token=epoch,plan=props.planId,list=[...selectedLibrary.value];try{for(const it of list){if(token!==epoch)return;await deletePlanMaterialClaim(plan,it.id!);if(token!==epoch)return;library.value=library.value.filter(x=>x.id!==it.id);selected.value.delete(it.uid)}}finally{if(token===epoch)await load()}})}
function predicateEditors(list:MaterialCondition[]=[]):PredicateEditor[]{return list.map(c=>typeof c==='string'?{field:'other',op:'raw',values:'',raw:c,universe:'',original:c}:{field:c.field||'other',op:c.op||'raw',values:['and','or'].includes(c.op||'')?'组合条件（完整保留）':(c.values||[]).join('、'),raw:c.raw||'',universe:c.universe||'',original:clone(c),opaque:['and','or'].includes(c.op||'')})}
function openEdit(it:ImportRow){error.value='';scopeItem.value=null;editItem.value=it;edit.value=clone(it);predicates.value=predicateEditors(it.conditions);exceptions.value=predicateEditors(it.exceptions);void nextTick(()=>editorContent.value?.focus())}
function closeEdit(){if(busy.value)return;edit.value=null;editItem.value=null;error.value=''}
function buildPredicates(list:PredicateEditor[]):MaterialCondition[]{return list.map(c=>{
 if(c.original!==undefined){const before=predicateEditors([c.original])[0]!;if(c.opaque||(['field','op','values','raw','universe'] as const).every(key=>c[key]===before[key]))return clone(c.original)}
 return {...((c.original&&typeof c.original==='object')?c.original:{}),field:c.field,op:c.op,raw:c.raw,universe:c.universe,values:c.values.split(/[、,，]/).map(x=>x.trim()).filter(Boolean),status:c.op==='raw'?'unresolved':'resolved'}
})}
async function saveEdit(){const target=editItem.value,next=edit.value;if(!target||!next)return;await run(async()=>{const token=epoch,plan=props.planId;next.conditions=buildPredicates(predicates.value);next.exceptions=buildPredicates(exceptions.value);if(next.destination==='qa')next.content=next.answer||'';if(next.content!==target.content&&next.value===target.content)next.value=next.content;next.fact_type=hasCondition(next)?'conditional':next.polarity;next.polarity_issue='';next.condition_issue='';next.needs_confirmation=false;if(next.id){await updatePlanMaterialClaim(plan,next.id,toInput(next));if(token!==epoch)return;await load();if(token!==epoch)return}else{draft.value=draft.value.map(it=>it.uid===target.uid?clone(next):it);draft.value=compareLibrary(draft.value,library.value);persist()}editItem.value=null;edit.value=null})}
function openScope(it:ImportRow){if(scopeItem.value?.uid===it.uid){scopeItem.value=null;return};scopeItem.value=it;scopeChoices.value=objectKeys(it).filter(k=>k!=='unresolved');scopeSearch.value=''}
function toggleScope(key:string){if(key==='plan'){scopeChoices.value=scopeChoices.value.includes('plan')?[]:['plan'];return};const next=scopeChoices.value.filter(k=>k!=='plan');scopeChoices.value=next.includes(key)?next.filter(k=>k!==key):[...next,key]}
function targetForKey(key:string):MaterialObjectTarget{if(key==='plan')return {kind:'plan'};if(key.startsWith('store:'))return {kind:'store',store_name:key.slice(6)};const link=linkObjects.value.find(l=>l.id===Number(key.slice(5)));if(!link)throw Error('链接已移除，请刷新');return {kind:'product',link_id:link.id,link_key:link.link_key}}
async function saveScope(){const target=scopeItem.value;if(!target)return;await run(async()=>{const token=epoch,plan=props.planId;if(!scopeChoices.value.length)throw Error('请至少选择一个归属对象');const next=assignedTargets(clone(target),scopeChoices.value.map(targetForKey));next.needs_confirmation=false;if(target.id){await updatePlanMaterialClaim(plan,target.id,toInput(next));if(token!==epoch)return;await load();if(token!==epoch)return}else{draft.value=draft.value.map(it=>it.uid===target.uid?next:it);draft.value=compareLibrary(draft.value,library.value);if(canConfirm(next))selected.value.add(next.uid);persist()}scopeItem.value=null})}
function openBindings(){bindingsOpen.value=!bindingsOpen.value;if(bindingsOpen.value){bindingsDraft.value=clone(storeObjects.value);newStoreName.value=''}}
function addStore(){const name=newStoreName.value.trim();if(!name||genericStore(name))return;error.value='';if(bindingsDraft.value.some(s=>s.name===name)){error.value='门店名称已存在';return};bindingsDraft.value.push({name,link_ids:[]});newStoreName.value=''}
async function saveBindings(){await run(async()=>{const token=epoch,plan=props.planId;const out=await savePlanMaterialObjects(plan,catalogRevision.value,clone(bindingsDraft.value));if(token!==epoch)return;catalogStores.value=out.stores;catalogRevision.value=out.revision;bindingsOpen.value=false;notice.value='门店与链接的关联已保存。'})}
function dismissInlineActions(event:MouseEvent){
 const target=event.target instanceof Element?event.target:null
 if(!target?.closest('.scope-anchor'))scopeItem.value=null
 if(!target?.closest('.claim-remove'))pendingClaimRemoval.value=null
}
onMounted(()=>document.addEventListener('click',dismissInlineActions))
function openSplit(it:ImportRow){error.value='';splitItem.value=it;splitRows.value=[];splitText.value=it.content}
async function modelSplit(operation:'split'|'attribute_split'){const target=splitItem.value;if(!target)return;await run(async()=>{const token=epoch;const out=await reviewPlanMaterialClaims(props.planId,operation,[{...toInput(target),content:splitText.value}]);if(token!==epoch)return;if(!out.items?.length)throw Error('没有可由原文支持的拆分，请手动分行调整');splitRows.value=out.items.map(row);splitText.value=splitRows.value.map(it=>`${it.topic}：${it.content}`).join('\n')})}
async function saveSplit(){const target=splitItem.value;if(!target)return;await run(async()=>{
 const lines=splitText.value.split('\n').map(x=>x.trim()).filter(Boolean);if(!lines.length||lines.length>500)throw Error('请拆分为1至500条资料')
 const parts=lines.map((line,i)=>{const m=line.match(/^([^：:]{1,80})[：:]\s*(.+)$/),content=m?.[2]||line;return {...clone(target),id:undefined,uid:crypto.randomUUID(),replaces_id:target.id?undefined:i===0?target.replaces_id:undefined,claim_key:m?.[1]||target.claim_key,topic:m?.[1]||target.topic,attribute:m?.[1]||target.attribute,content,value:content,answer:target.destination==='qa'?content:target.answer,needs_split:false,atomicity_reason:'',needs_confirmation:!target.id,rowState:'new' as const}})
 if(target.id){
  if(!target.revision)throw Error('请刷新库中资料后再拆分')
  const token=epoch,out=await splitPlanMaterialClaim(props.planId,target.id,target.revision,parts.map(toInput));if(token!==epoch)return
  library.value=library.value.filter(it=>it.id!==target.id);selected.value.delete(target.uid);splitItem.value=null;questions.value=[]
  source.value='library';view.value='object';objectAttribute.value='all';topic.value='all';filter.value='all';search.value=''
  const refreshed=await load();if(token!==epoch)return
  notice.value=`已拆分为 ${out.added} 条并入库，原条目已替换。${refreshed?'':'请点击“刷新库”查看新条目。'}`
 }else{draft.value=draft.value.flatMap(it=>it.uid===target.uid?parts:it);source.value='draft';setSelected();persist();splitItem.value=null;questions.value=[]}
})}
function supply(it:ImportRow){openEdit(it);if(edit.value){edit.value.destination='qa';edit.value.question=it.question||it.content;edit.value.answer=''}}
function resetFilters(){search.value='';topic.value='all';filter.value='all';object.value='all';objectAttribute.value='all';expandedObjects.value=new Set();question.value=''}
watch(source,()=>{objectAttribute.value='all';topic.value='all'})
watch(topic,value=>{if(value!=='all')objectAttribute.value='all'})
watch(()=>JSON.stringify(all.value.map(toInput)),()=>{questionRevision++;questionsLoading.value=false;questions.value=[];question.value=''},{flush:'sync'})
watch([()=>props.planId,actorKey],()=>{epoch++;pendingClaimRemoval.value=null;busy.value=false;questionsLoading.value=false;loaded.value=false;library.value=[];selected.value=new Set();libraryRevision.value='';importRows.value=[];importLibrary.value=[];importChoices.value={};edit.value=null;editItem.value=null;splitItem.value=null;scopeItem.value=null;confirmOpen.value=false;duplicateActionKey.value='';duplicateChoices.value={};view.value='object';error.value='';notice.value='';conflicts.value=[];catalogLinks.value=[];catalogStores.value=[];catalogRevision.value=0;bindingsOpen.value=false;bindingsDraft.value=[];source.value='draft';resetFilters();restore();void load()},{immediate:true})
watch([text,draft],persist,{deep:true})
onBeforeUnmount(()=>{epoch++;document.removeEventListener('click',dismissInlineActions)})
</script>

<template>
<section class="material-import">
 <div class="composer">
  <header><h2>资料导入</h2><span>{{ [...text].length }} 字</span></header>
  <p>粘贴资料，分析并核对归属后确认入库。</p>
  <label class="sr-only" for="material-raw">粘贴资料</label>
  <textarea id="material-raw" v-model="text" :disabled="busy" />
  <div class="actions composer-actions"><button class="primary" :disabled="busy||!loaded" @click="analyze">{{ busy ? '处理中…' : '分析' }}</button><button :disabled="busy||!draft.length" @click="clearDraft">清除草稿</button><button class="danger" :disabled="busy||!loaded||!library.length" @click="clearLibrary">清除库中数据</button></div>
  <p v-if="notice" role="status" class="notice">{{ notice }}</p><p v-if="error" role="alert" class="error">{{ error }}</p>
  <div class="sources"><button v-for="s in (['draft','library','all'] as const)" :key="s" :class="{active:source===s}" @click="source=s;question=''">{{ s==='draft'?'草稿':s==='library'?'库':'全部' }} {{ s==='draft'?draft.length:s==='library'?library.length:all.length }}</button><button :disabled="busy" @click="load">刷新库</button></div>
 </div>
 <div v-if="all.length" class="reviews"><button :class="{active:view==='object'}" @click="setView('object')">按对象</button><button :class="{active:view==='todo'}" @click="setView('todo')">待处理 <b>{{ counts.todo }}</b></button><button class="duplicate-tab" :class="{active:view==='duplicates', 'has-duplicates':duplicates.length>0}" @click="setView('duplicates')">重复属性 <b>{{ duplicates.length }}</b></button><span class="muted">{{ view==='object'?'按对象查看：'+labelFor(object):view==='todo'?'尚未确认归属的属性':'属性值和原文一致时提示重复，选中一条保留' }}</span></div>
 <div v-if="duplicates.length&&view!=='duplicates'" class="duplicate-alert" role="status"><span><b>发现 {{ duplicates.length }} 组重复属性</b>，请比较后处理。</span><button :disabled="busy" @click="setView('duplicates')">查看重复属性</button></div>
 <div v-if="all.length" class="review-layout">
  <aside class="object-tree">
   <div class="tree-heading"><b>对象</b><button :disabled="busy" @click="openBindings">门店关联</button></div>
   <section v-for="(g,index) in treeSections" :key="index"><p v-if="g.label" class="tree-group">{{ g.label }}</p><template v-for="key in g.keys" :key="key">
    <div class="tree-row" :class="{'pending-row':key==='unresolved','link-row':key.startsWith('link:')}"><input type="checkbox" :aria-label="key==='all'?'选择全部属性':key==='plan'?'选择全局属性':key==='unresolved'?'选择待归属属性':'选择 '+labelFor(key)+' 的属性'" :disabled="busy||key==='unresolved'" :checked="groupChecked(key)" @change="selectGroup(key)"/>
     <template v-if="key.startsWith('link:')&&renamingLinkId===Number(key.slice(5))"><input ref="renameInput" v-model="renamingName" class="rename-input" maxlength="50" :aria-label="'修改 '+labelFor(key)+' 的显示名称'" placeholder="留空恢复默认名称" :disabled="busy" @keydown.enter.prevent="saveRenameLink" @keydown.esc.prevent="cancelRenameLink"/><button class="rename-action" :disabled="busy" @click.stop="saveRenameLink">保存</button><button class="rename-action" :disabled="busy" @click.stop="cancelRenameLink">取消</button></template>
     <template v-else><button class="tree-object" :class="{active:object===key,expandable:key!=='all',expanded:expandedObjects.has(key)}" :title="subtitleFor(key)" :aria-expanded="key==='all'?undefined:expandedObjects.has(key)" :aria-controls="key==='all'?undefined:'attributes-'+key" @click="selectObject(key)"><span>{{ labelFor(key) }}</span><small>{{ key==='all'?currentRows.length:countFor(key) }}</small></button><button v-if="key.startsWith('link:')" class="rename-link" :disabled="busy" title="修改显示名称" :aria-label="'修改 '+labelFor(key)+' 的显示名称'" @click.stop="startRenameLink(key)">✎</button></template></div>
    <div v-if="key!=='all'&&expandedObjects.has(key)" :id="'attributes-'+key" class="tree-attributes" :aria-label="labelFor(key)+'的属性'"><button v-for="attr in attributesFor(key)" :key="attr.key" :class="{active:object===key&&objectAttribute===attr.key}" :aria-pressed="object===key&&objectAttribute===attr.key" @click="selectAttribute(key,attr.key)"><span>{{ attr.label }}</span><small>{{ attr.count }}</small></button><span v-if="!countFor(key)" class="tree-empty">暂无属性</span></div>
   </template></section>
  </aside>
  <main>
   <section v-if="bindingsOpen" class="bindings-panel">
    <h3>门店与链接关联</h3><p>关联后，该门店的属性适用于选中的链接。服务直接按属性分配给链接。</p>
    <div class="add-store"><input v-model="newStoreName" aria-label="门店名称" placeholder="例如：王家店"/><button :disabled="busy||!newStoreName.trim()" @click="addStore">添加门店</button></div>
    <div v-for="(store,i) in bindingsDraft" :key="store.name" class="store-binding"><b>{{ store.name }}</b><details class="binding-select"><summary>{{ store.link_ids.length?'已关联 '+store.link_ids.map(id=>labelFor('link:'+id)).join('、'):'选择关联链接' }}</summary><label v-for="link in linkObjects" :key="link.id" class="compact-option"><input type="checkbox" v-model="store.link_ids" :value="link.id" :disabled="busy"/><span>{{ labelFor('link:'+link.id) }}<small>{{ link.product_name }}</small></span></label></details><button :disabled="busy" @click="bindingsDraft.splice(i,1)">移除</button></div>
    <div class="actions"><button :disabled="busy" @click="bindingsOpen=false">取消</button><button class="primary" :disabled="busy" @click="saveBindings">保存关联</button></div>
   </section>
   <p class="scope-help">全局属性适用于本方案全部链接；待归属属性需手动分配。{{ object.startsWith('link:')?'全局属性统一在“全局”查看，仍适用于本链接。':'' }}</p>
   <div class="filters"><input v-model="search" aria-label="搜索资料" placeholder="搜索对象、属性、内容、原文"/><select v-model="topic" aria-label="属性筛选"><option value="all">全部属性</option><option v-for="t in topics" :key="t">{{ t }}</option></select><button @click="resetFilters">清空</button></div>
   <div class="summary"><button :disabled="busy||!visible.length" @click="selectRows(visible.filter(it=>!!it.id||eligible(it)))">全选当前</button><button v-for="s in (['all','todo','risk','split','conflict'] as const)" :key="s" :class="{active:filter===s}" @click="filter=s"><b>{{ counts[s] }}</b> {{ ({all:'全部',todo:'待归属',risk:'风险提示',split:'待拆分',conflict:'冲突'})[s] }}</button></div>
   <div v-for="(c,i) in conflicts" :key="i" class="banner warn"><b>模型提示冲突 · {{ c.topic }}</b><p>{{ c.issue }}</p><p v-for="statement in c.statements" :key="statement">{{ statement }}</p><button @click="conflicts.splice(i,1)">知道了</button></div>
   <section v-if="view==='duplicates'" class="duplicate-list" aria-label="重复属性对比">
    <section v-for="group in visibleDuplicates" :key="group.key" class="duplicate-group">
     <header class="duplicate-heading"><div><h3>{{ labelFor(group.objectKey) }} · {{ group.rows[0]?.topic||group.rows[0]?.claim_key }} <span>{{ group.rows.length }} 条</span></h3><p>属性值和原文一致，请选择需要保留的条目。</p></div><span class="duplicate-badge">重复属性</span></header>
     <div class="duplicate-options" role="radiogroup" :aria-label="labelFor(group.objectKey)+'重复属性保留选择'"><label v-for="(candidate,i) in group.rows" :key="candidate.uid" class="duplicate-option" :class="{picked:chosenDuplicate(group)?.uid===candidate.uid}"><input type="radio" :name="'duplicate-'+group.key" :aria-label="'保留第'+(i+1)+'条 '+candidate.content" :checked="chosenDuplicate(group)?.uid===candidate.uid" :disabled="busy" @change="duplicateChoices[group.key]=candidate.uid;duplicateActionKey=''"/><div><div class="duplicate-meta"><b>{{ scopeLabel(candidate) }}</b><span>{{ candidate.id?'库中资料':'草稿' }}</span><span v-if="candidate.polarity==='negative'" class="error">否定</span></div><p v-if="candidate.polarity_issue||candidate.condition_issue" class="error">{{ candidate.polarity_issue }} {{ candidate.condition_issue }}</p><p v-if="isRisk(candidate)" class="error">风险提示：{{ candidate.risks?.map(r=>r.reason).filter(Boolean).join('；')||'请核对原文依据' }}</p><p class="duplicate-content">{{ candidate.destination==='qa'?candidate.question+'：'+candidate.answer:candidate.content }}</p><p class="muted">属性值：{{ candidate.value }}</p><p v-if="candidate.conditions.length" class="muted">条件：{{ candidate.conditions.map(conditionLabel).join('；') }}</p><p v-if="candidate.exceptions?.length" class="muted">例外：{{ candidate.exceptions.map(conditionLabel).join('；') }}</p><details v-if="candidate.source_sentence||candidate.source_quote"><summary>查看原文</summary><p>{{ candidate.source_sentence||candidate.source_quote }}</p></details></div></label></div>
     <p v-if="error&&duplicateActionKey===group.key" class="error" role="alert">{{ error }}</p>
     <div class="duplicate-actions"><span>仅保留选中条目在本对象下的归属，其它对象的资料保留。</span><button class="primary" :disabled="busy||!chosenDuplicate(group)" @click="resolveDuplicate(group)">保留</button></div>
    </section><p v-if="!visibleDuplicates.length" class="empty">当前没有重复属性。</p>
   </section>
   <template v-else><article v-for="it in visible" :key="it.uid" class="claim" :class="{conflict:['conflict','lib_conflict'].includes(it.rowState||'')}">
    <input type="checkbox" :aria-label="'选择 '+it.content" :disabled="busy||(!it.id&&!eligible(it))" :checked="selected.has(it.uid)" @change="toggle(it.uid)"/>
    <div class="claim-body"><div class="claim-head"><b>{{ scopeLabel(it) }}</b><span class="accent">· {{ it.topic||it.attribute||'其它' }}</span><small v-if="it.id">库</small><small>{{ ({fact:'事实',qa:'问答',word:'词卡',material:'素材',gap:'缺口'})[it.destination||'fact'] }}</small><small v-if="it.polarity==='negative'">否定</small><small v-if="hasCondition(it)">条件</small><small v-if="isTodo(it)" class="warn">待归属</small><button v-if="duplicateUIDs.has(it.uid)" class="duplicate-badge" @click="setView('duplicates')">重复属性</button><small v-if="it.needs_split" class="warn">可能未拆分</small><small v-if="it.rowState==='in_library'">库中已有</small><label class="benefit-toggle"><input type="checkbox" :aria-label="'标记'+it.content+'为福利'" :checked="!!it.is_benefit" :disabled="busy" @change="toggleBenefit(it)"/><span>福利</span></label></div>
     <div class="value" v-if="it.destination==='qa'"><div>Q：{{ it.question }}</div><div>A：{{ it.answer }}</div></div><div v-else class="value">{{ it.content }}</div>
     <p v-if="it.value&&it.value!==it.content" class="muted">标准值：{{ it.value }}</p><p v-if="it.conditions.length" class="muted">条件：{{ it.conditions.map(conditionLabel).join('；') }}</p><p v-if="it.exceptions?.length" class="muted">例外：{{ it.exceptions.map(conditionLabel).join('；') }}</p>

     <p v-if="it.source_quote" class="muted">原句摘要：{{ it.source_quote }}</p>
      <p v-if="it.source_sentence&&it.source_sentence!==it.source_quote" class="muted">原句：{{ it.source_sentence }}</p>
      <p v-if="it.oldContent" class="muted">原值：{{ it.oldContent }}</p><p v-if="it.polarity_issue||it.condition_issue" class="error">{{ it.polarity_issue }} {{ it.condition_issue }}</p>
     <div v-if="isRisk(it)" class="risk"><b>风险提示（不等于正式审核放行）</b><div v-for="(risk,i) in it.risks" :key="i"><p>{{ risk.text }} · {{ risk.reason }}</p><p>建议：{{ risk.suggestion }} <button :disabled="busy" @click="openEdit(it)">修改表述</button></p></div><p v-if="it.p0_hits?.length">⛔ 含需正式审核的表达。入库不会绕过已有播放审核。</p></div>
     <p v-if="it.destination==='word'" class="muted">词义保留在草稿，不能当作商品事实写入语义库。</p>
     <div class="actions"><button v-if="it.destination==='gap'" :disabled="busy" @click="supply(it)">补充事实</button><button :disabled="busy" @click="openEdit(it)">编辑</button><button v-if="it.destination!=='gap'" :disabled="busy" @click="openSplit(it)">再拆分</button><span class="scope-anchor" @keydown.esc="scopeItem=null"><button :disabled="busy" :aria-expanded="scopeItem?.uid===it.uid" @click="openScope(it)">归属分配 ▾</button>
      <div v-if="scopeItem?.uid===it.uid" class="scope-popover" role="group" aria-label="属性归属多选"><input v-model="scopeSearch" aria-label="搜索归属对象" placeholder="搜索链接或门店"/><div class="scope-options"><label v-for="key in scopeOptions" :key="key" class="compact-option"><input type="checkbox" :aria-label="labelFor(key)" :checked="scopeChoices.includes(key)" :disabled="busy" @change="toggleScope(key)"/><span>{{ labelFor(key) }}<small>{{ subtitleFor(key) }}</small></span></label></div><div class="scope-footer"><span>已选 {{ scopeChoices.length }} 个</span><button :disabled="busy" @click="scopeItem=null">取消</button><button class="primary" :disabled="busy||!scopeChoices.length" @click="saveScope">确定分配</button></div></div>
     </span><button type="button" class="danger claim-remove" :class="{confirming:pendingClaimRemoval===it.uid}" :disabled="busy" @click="remove(it)" @blur="pendingClaimRemoval===it.uid&&(pendingClaimRemoval=null)" @keydown.esc.stop="pendingClaimRemoval=null">{{ pendingClaimRemoval===it.uid?'确认删除':'删除' }}</button></div>
    </div>
   </article>
   <p v-if="!visible.length" class="empty">当前筛选下没有资料。</p></template>
  </main>
 </div>
 <p v-else class="empty">{{ loaded?'还没有资料。粘贴后点击“分析”。':'正在读取资料…' }}</p>
 <footer v-if="draft.length||selectedLibrary.length" class="actionbar"><span>已选 {{ chosen.length }} 项草稿 / {{ selectedLibrary.length }} 项库中资料</span><button :disabled="busy" @click="selected=chosen.length?new Set():new Set(draft.filter(canConfirm).map(it=>it.uid))">{{ chosen.length?'取消全选':'全选可入库' }}</button><span v-if="unresolvedConflicts" class="error">{{ unresolvedConflicts }} 项重复草稿待处理</span><button v-if="selectedLibrary.length" class="danger" :disabled="busy" @click="removeSelected">移除选中库资料</button><button class="primary" :disabled="busy||!loaded||!chosen.length" @click="prepareConfirm">确认入库</button></footer>
 <div v-if="confirmOpen||edit||splitItem" class="backdrop" @click.self="!busy&&(confirmOpen=false,edit=null,splitItem=null)">
  <section class="dialog" :class="{'editor-dialog':!!edit,'import-dialog':confirmOpen}" role="dialog" aria-modal="true" :aria-label="edit?'修改表述':'资料操作'" @keydown.esc="edit&&!busy&&closeEdit()">
   <template v-if="confirmOpen"><h3>确认入库</h3><p>本次选择 {{ importRows.length }} 条草稿，其中 {{ importAppendCount }} 条新属性直接追加。</p><p v-if="importGroups.length" class="import-help">库中已有的属性，请逐组选择替换或保留。未选择前不能入库。</p>
    <section v-for="group in importGroups" :key="group.key" class="import-decision"><h4>{{ group.draft[0]?.topic||group.draft[0]?.claim_key }}</h4><div class="import-compare"><section><b>本次草稿</b><div v-for="it in group.draft" :key="it.uid"><p class="import-scope">{{ scopeLabel(it) }} <span v-if="it.polarity==='negative'">· 否定</span></p><p>{{ it.content }}</p><p v-if="it.conditions.length" class="muted">条件：{{ it.conditions.map(conditionLabel).join('；') }}</p><p v-if="it.exceptions?.length" class="muted">例外：{{ it.exceptions.map(conditionLabel).join('；') }}</p></div></section><section><b>库中已有</b><div v-for="it in group.library" :key="it.uid"><p class="import-scope">{{ scopeLabel(it) }} <span v-if="it.polarity==='negative'">· 否定</span></p><p>{{ it.content }}</p><p v-if="it.conditions.length" class="muted">条件：{{ it.conditions.map(conditionLabel).join('；') }}</p><p v-if="it.exceptions?.length" class="muted">例外：{{ it.exceptions.map(conditionLabel).join('；') }}</p></div></section></div><div class="import-options"><label><input type="radio" :name="'import-'+group.key" :value="'replace'" v-model="importChoices[group.key]" :disabled="busy"/>替换为本次草稿</label><label><input type="radio" :name="'import-'+group.key" :value="'keep'" v-model="importChoices[group.key]" :disabled="busy"/>保留库中的</label></div><p v-if="importChoices[group.key]==='replace'" class="import-result">将移除以上 {{ group.library.length }} 条库中记录，写入 {{ group.draft.length }} 条本次草稿；仅替换本次草稿明确选择的对象，其它对象的库中资料保留。</p><p v-else-if="importChoices[group.key]==='keep'" class="import-result">库中记录保持，本组 {{ group.draft.length }} 条草稿不入库。</p></section>
    <p class="import-help">待归属及尚未核对的条件条目保留在草稿。清除或入库不会修改正在直播的正式事实。</p><div class="actions import-confirm-actions"><button :disabled="busy" @click="confirmOpen=false">取消</button><button class="primary" :disabled="busy||!importReady" @click="confirm">{{ busy?'入库中…':'确认' }}</button></div></template>
   <template v-else-if="edit">
    <header class="editor-header"><div><h3>修改表述</h3><p>{{ scopeLabel(edit) }}<span class="editor-state">{{ edit.id?'库中资料':'草稿' }}</span></p></div><button class="editor-close" aria-label="关闭修改表述" :disabled="busy" @click="closeEdit">×</button></header>
    <div class="editor-body"><fieldset class="editor-fields" :disabled="busy">
     <div v-if="edit.risks?.length" class="editor-risk-note"><b>请核对表述</b><span>{{ [...new Set(edit.risks.map(r=>r.reason).filter(Boolean))].join('；') }}</span></div>
     <label class="editor-field">属性名称<input v-model="edit.topic" placeholder="例如：门店价、配送范围"/></label>
     <template v-if="edit.destination==='qa'"><label class="editor-field">问题<input v-model="edit.question"/></label><label class="editor-field editor-content">答案<textarea ref="editorContent" v-model="edit.answer" rows="4" placeholder="填写给用户的回答"/></label></template>
     <label v-else class="editor-field editor-content">内容<textarea ref="editorContent" v-model="edit.content" rows="4" placeholder="修改这条资料的表述"/></label>
     <details v-if="edit.source_quote||edit.source_sentence" class="editor-source"><summary>查看原文</summary><blockquote>{{ edit.source_sentence||edit.source_quote }}</blockquote></details>
     <details class="editor-fold editor-rules" :open="!!(predicates.length||exceptions.length)"><summary><span>条件与例外</span><small>{{ predicates.length||exceptions.length?`${predicates.length} 条条件 · ${exceptions.length} 条例外`:'未设置' }}</small></summary>
      <div class="editor-rule-groups"><section v-for="(list,idx) in [predicates,exceptions]" :key="idx" class="editor-rule-group"><div class="editor-group-heading"><b>{{ idx?'例外':'适用条件' }}</b><button :disabled="busy" @click="list.push({field:'region',op:'in',values:'',raw:'',universe:''})">＋ 添加{{ idx?'例外':'条件' }}</button></div><p v-if="!list.length" class="editor-empty-rule">{{ idx?'没有例外限制':'没有额外条件' }}</p>
       <div v-for="(c,i) in list" :key="i" class="editor-predicate"><div class="editor-rule-title"><span>{{ idx?'例外':'条件' }} {{ i+1 }}</span><button class="editor-remove" :disabled="busy" @click="list.splice(i,1)">移除</button></div>
        <p v-if="c.opaque" class="editor-composite">{{ c.raw||'已有组合条件' }}<small>组合条件已完整保留</small></p>
        <template v-else><div v-if="c.op!=='raw'" class="editor-rule-fields"><label>判断内容<select v-model="c.field" aria-label="条件字段"><option v-for="f in predicateFields" :key="f.value" :value="f.value">{{ f.label }}</option><option v-if="!predicateFields.some(f=>f.value===c.field)" :value="c.field">{{ c.field }}</option></select></label><label>判断方式<select v-model="c.op" aria-label="判断方式"><option v-for="op in predicateOps.filter(o=>!['and','or'].includes(o.value))" :key="op.value" :value="op.value">{{ op.label }}</option></select></label><label class="editor-rule-values">条件值<input v-model="c.values" aria-label="条件值" placeholder="多个值用顿号分隔"/></label></div>
         <label v-if="c.op==='not_in'" class="editor-field">适用范围<select v-model="c.universe" aria-label="适用范围"><option value="">请选择</option><option value="china_provinces">全国省份</option><option v-if="c.universe&&c.universe!=='china_provinces'" :value="c.universe">{{ c.universe }}</option></select></label>
         <details class="editor-rule-note" :open="c.op==='raw'"><summary>原文说明{{ c.op==='raw'?'（尚待核对）':'' }}</summary><label>条件原话<input v-model="c.raw" aria-label="条件原话" placeholder="例如：满99元、新疆除外"/></label><label v-if="c.op!=='not_in'&&c.universe">适用范围<input v-model="c.universe" aria-label="已有适用范围"/></label></details></template>
       </div></section></div>
     </details>
     <details class="editor-fold editor-settings"><summary><span>更多设置</span><small>分类、标准值等</small></summary><div class="editor-settings-grid"><label>分类<select v-model="edit.destination"><option value="fact">事实</option><option value="qa">问答</option><option value="word">词义</option><option value="material">表达素材</option><option value="gap">待补问题</option></select></label><label>事实表达<select v-model="edit.polarity"><option value="positive">肯定</option><option value="negative">否定</option></select></label><label>属性键<input v-model="edit.claim_key"/></label><label>标准值<input v-model="edit.value"/></label></div></details>
    </fieldset></div>
    <footer class="editor-footer"><p v-if="error" role="alert" class="error">{{ error }}</p><div class="editor-save-row"><span>{{ edit.id?'保存后更新这条库中资料。':'保存为草稿，确认入库后才生效。' }}</span><div class="actions"><button :disabled="busy" @click="closeEdit">取消</button><button class="primary" :disabled="busy||!editCanSave" @click="saveEdit">{{ busy?'保存中…':edit.id?'保存修改':'保存草稿' }}</button></div></div></footer>
   </template>
   <template v-else-if="splitItem"><h3>再拆分</h3><p>每行一条，可写“属性：值”。{{ splitItem.id?'保存后直接入库并替换原条目。':'只替换当前草稿，其它草稿保留。' }}</p><textarea v-model="splitText" :disabled="busy" aria-label="拆分内容"/><div class="actions"><button :disabled="busy" @click="modelSplit('split')">模型重拆</button><button :disabled="busy" @click="modelSplit('attribute_split')">属性切分</button><button :disabled="busy" @click="splitItem=null">取消</button><button class="primary" :disabled="busy||!splitText.trim()" @click="saveSplit">{{ busy?'保存中…':'保存切分' }}</button></div></template>
   <p v-if="error&&!edit" role="alert" class="error">{{ error }}</p>
  </section>
 </div>
</section>
</template>

